CREATE OR REPLACE FUNCTION public.tmp_rescore_zero_ls() RETURNS TABLE(u INT, p INT, f INT, ur INT) LANGUAGE plpgsql AS $func$ DECLARE v_u INT; v_p INT; v_f INT; v_ur INT; BEGIN UPDATE pplp_scores SET light_score = ROUND((COALESCE(pillar_t,0)+COALESCE(pillar_s,0)+COALESCE(pillar_h,0)+COALESCE(pillar_c,0)+COALESCE(pillar_u,0))/5.0,2), vvu_score = ROUND((COALESCE(pillar_t,0)+COALESCE(pillar_s,0)+COALESCE(pillar_h,0)+COALESCE(pillar_c,0)+COALESCE(pillar_u,0))/5.0,2), decision = (CASE WHEN COALESCE(pillar_t,0)>=30 AND ((COALESCE(pillar_t,0)+COALESCE(pillar_s,0)+COALESCE(pillar_h,0)+COALESCE(pillar_c,0)+COALESCE(pillar_u,0))/5.0)>=15 THEN 'pass' ELSE 'fail' END)::pplp_decision, decision_reason = CASE WHEN COALESCE(pillar_t,0)>=30 AND ((COALESCE(pillar_t,0)+COALESCE(pillar_s,0)+COALESCE(pillar_h,0)+COALESCE(pillar_c,0)+COALESCE(pillar_u,0))/5.0)>=15 THEN 'RESCORED_v25_RECOMPUTED_LS' ELSE 'LEGITIMATE_FAIL_v25' END, scoring_engine_version = 'v2.5' WHERE decision='fail' AND scoring_engine_version='v2.5' AND COALESCE(light_score,0)=0; GET DIAGNOSTICS v_u = ROW_COUNT; UPDATE pplp_actions a SET status='scored' FROM pplp_scores s WHERE s.action_id=a.id AND s.decision_reason='RESCORED_v25_RECOMPUTED_LS' AND a.status!='minted'; PERFORM recompute_user_light_score(actor_id) FROM (SELECT DISTINCT a.actor_id FROM pplp_actions a JOIN pplp_scores s ON s.action_id=a.id WHERE s.decision_reason='RESCORED_v25_RECOMPUTED_LS') sub; SELECT COUNT(*) INTO v_p FROM pplp_scores WHERE decision_reason='RESCORED_v25_RECOMPUTED_LS'; SELECT COUNT(*) INTO v_f FROM pplp_scores WHERE decision_reason='LEGITIMATE_FAIL_v25'; SELECT COUNT(DISTINCT a.actor_id) INTO v_ur FROM pplp_actions a JOIN pplp_scores s ON s.action_id=a.id WHERE s.decision_reason='RESCORED_v25_RECOMPUTED_LS'; RETURN QUERY SELECT v_u, v_p, v_f, v_ur; END; $func$;